import{Spatial,clamp,mix,smooth,segment,MIN_X,MAX_X,MIN_Z,MAX_Z}from'./core.js';
export const ROAD_MATERIALS={earth:{name:'夯土',color:'#b5a07b'},gravel:{name:'浅色碎石',color:'#b9b8a5'},stone:{name:'青灰石板',color:'#9ba6a1'},wood:{name:'木板',color:'#a18458'}};
export const BRIDGE_MATERIALS={wood:{name:'木桥',color:'#a18458'},stone:{name:'石桥',color:'#9da6a3'}};
// Editable centreline plus a horizontal cross section. The shoulder blends back
// to the original ground and is sampled by the same live terrain renderer.
export class Earthworks{
 constructor(geo,records=[]){this.geo=geo;this.version=0;this.changeBounds=null;this.active=null;this.records=[];this.spatial=new Spatial(100);this.segments=[];this.dirty=new Set();this.touched=new Set();this.reset(records);geo.earthworks=this;}
 reset(records=[]){this.active=null;this.records=[];this.spatial=new Spatial(100);this.segments=[];const old=[...this.touched,...this.dirty];this.dirty=new Set(old);this.changeBounds=null;for(const key of old){const[i,j]=key.split(':').map(Number);this.expand([i*100-10000,j*100-8000,i*100-9900,j*100-7900]);}
  for(const record of records){if(!Array.isArray(record.points)||record.points.length<2)continue;const r={material:ROAD_MATERIALS[record.material]?record.material:'earth',bridgeMaterial:BRIDGE_MATERIALS[record.bridgeMaterial]?record.bridgeMaterial:'wood',width:clamp(Number(record.width)||2.4,1.5,6),points:record.points.filter(p=>Array.isArray(p)&&p.length>=4&&p.slice(0,3).every(Number.isFinite)).map(p=>[clamp(p[0],MIN_X+1,MAX_X-1),clamp(p[1],MIN_Z+1,MAX_Z-1),p[2],!!p[3]])};if(r.points.length<2)continue;this.records.push(r);for(let i=1;i<r.points.length;i++)this.index(r,r.points[i-1],r.points[i]);}this.version++;
 }
 begin(x,z,options){this.stop();const r={material:options.material||'earth',bridgeMaterial:options.bridgeMaterial||'wood',width:clamp(Number(options.width)||2.4,1.5,6),points:[]};this.records.push(r);this.active=r;this.add(x,z,true);}
 stop(){if(this.active?.points.length<2)this.records.splice(this.records.indexOf(this.active),1);this.active=null;}
 point(x,z){const w=this.geo.waterAt(x,z),raw=this.geo.hydrology?.ground(x,z)??this.geo.baseHeight(x,z),bridge=!!w&&w.depth>.15;return[x,z,bridge?Math.max(raw,w.height+.85):raw,bridge];}
 add(x,z,force=false){if(!this.active)return false;const last=this.active.points.at(-1);if(last&&Math.hypot(x-last[0],z-last[1])<1.1&&!force)return false;const p=this.point(x,z);if(last){const n=Math.ceil(Math.hypot(x-last[0],z-last[1])/2);for(let i=1;i<=n;i++){const q=i===n?p:this.point(mix(last[0],x,i/n),mix(last[1],z,i/n));this.active.points.push(q);const a=this.active.points.at(-2);this.index(this.active,a,q);}}else this.active.points.push(p);this.version++;return true;}
 index(record,a,b){const pad=record.width/2+Math.max(3,record.width*.8),s={record,a,b,bridge:a[3]||b[3],order:this.segments.length};this.segments.push(s);const bounds=[Math.min(a[0],b[0])-pad,Math.min(a[1],b[1])-pad,Math.max(a[0],b[0])+pad,Math.max(a[1],b[1])+pad];this.spatial.add(s,bounds);this.expand(bounds);for(let j=Math.max(0,Math.floor((bounds[1]+8000)/100));j<=Math.min(159,Math.floor((bounds[3]+8000)/100));j++)for(let i=Math.max(0,Math.floor((bounds[0]+10000)/100));i<=Math.min(199,Math.floor((bounds[2]+10000)/100));i++){this.dirty.add(i+':'+j);this.touched.add(i+':'+j);}}
 expand(b){const a=this.changeBounds;this.changeBounds=a?[Math.min(a[0],b[0]),Math.min(a[1],b[1]),Math.max(a[2],b[2]),Math.max(a[3],b[3])]:[...b];}
 nearest(x,z,bridges=false){let best=null;for(const s of this.spatial.at(x,z)){if(s.bridge!==bridges)continue;const q=segment([x,z],s.a,s.b),half=s.record.width/2,pad=Math.max(3,s.record.width*.8);if(q.distance>half+pad)continue;if(!best||q.distance<best.distance-.02||Math.abs(q.distance-best.distance)<.02&&s.order>best.order)best={...s,...q,half,pad,y:mix(s.a[2],s.b[2],q.t)};}return best;}
 height(x,z,base){const s=this.nearest(x,z);if(!s)return base;const t=1-smooth(s.half,s.half+s.pad,s.distance);return mix(base,s.y,t);}
 bridgeAt(x,z){const s=this.nearest(x,z,true);return s&&s.distance<=s.half?s.y+.04:null;}
 distance(x,z){let d=Infinity;for(const s of this.spatial.at(x,z))d=Math.min(d,segment([x,z],s.a,s.b).distance-s.record.width/2);return d;}
 undo(){this.stop();const removed=this.records.pop();if(!removed)return false;for(const s of this.segments)if(s.record===removed){const pad=removed.width+5;for(let j=Math.floor((Math.min(s.a[1],s.b[1])-pad+8000)/100);j<=Math.floor((Math.max(s.a[1],s.b[1])+pad+8000)/100);j++)for(let i=Math.floor((Math.min(s.a[0],s.b[0])-pad+10000)/100);i<=Math.floor((Math.max(s.a[0],s.b[0])+pad+10000)/100);i++)if(i>=0&&i<200&&j>=0&&j<160)this.dirty.add(i+':'+j);}this.reset(this.records);return true;}
 serialize(){return this.records.filter(r=>r.points.length>1).map(r=>({material:r.material,bridgeMaterial:r.bridgeMaterial,width:r.width,points:r.points}));}
 get length(){return this.segments.reduce((n,s)=>n+Math.hypot(s.a[0]-s.b[0],s.a[1]-s.b[1]),0);}
}
